#include <iostream>

void chuyen(int n, int di, int den) {
    if (n == 1) {
        std::cout << di << " -> " << den << "\n";
    } else {
        int trung_gian = 6 - di - den;
        chuyen(n - 1, di, trung_gian);
        std::cout << di << " -> " << den << "\n";
        chuyen(n - 1, trung_gian, den);
    }
}

int main() {
    int sotang = 0;
    if (std::cin >> sotang && sotang > 0) {
        chuyen(sotang, 1, 2);
    }
    return 0;
}

#include <iostream>

float luythua(float x, int n) {
    float kq = 1.0f;
    for (int i = 1; i <= n; ++i) {
        kq *= x;
    }
    return kq;
}

void print_repeat(int n) {
    for (int i = 1; i <= n; ++i) {
        std::cout << ".";
    }
    std::cout << "\n";
}

int main() {
    float x = 2.0f;
    int n = 3;
    print_repeat(n);
    std::cout << luythua(x, n) << "\n";
    return 0;
}

